    {
        return array_map(static fn (array $record): array => array_values(array_unique([...$record['fields'], ...array_keys($record['parents']), ...$record['version_columns'],
            ...array_filter([$record['organization_column'], $record['project_column'], $record['actor_column']]), ...array_keys($record['predicates'])])), self::records());
    }
