    public static function applyActorScope(string $type, Builder $query, User $actor, int $organizationId, AuthorizationService $authorization, AssistantDataAccessPolicy $policy): void
    {
        if ($type === 'core_specification') {
            $contracts = $policy->entityQuery($actor, $organizationId, 'contract');
            if ($contracts === null) { $query->whereRaw('1 = 0'); return; }
            $query->whereHas('contracts', static fn (Builder $linked): Builder => $linked->whereIn('contracts.id', $contracts->select('contracts.id')));
        }
        if ($type === 'core_customer_portal_comment') {
            $table = $query->getModel()->getTable();
            $query->where(function (Builder $comments) use ($actor, $organizationId, $policy, $table): void {
                $comments->whereRaw('1 = 0');
                foreach ([\App\Models\CustomerIssue::class => 'customer_issue', \App\Models\CustomerRequest::class => 'core_customer_request'] as $model => $parentType) {
                    $parents = $policy->entityQuery($actor, $organizationId, $parentType);
                    if ($parents === null) { continue; }
                    $parentTable = $parents->getModel()->getTable();
                    $morphClass = (new $model())->getMorphClass();
                    $comments->orWhere(static fn (Builder $scope): Builder => $scope->whereIn($table.'.commentable_type', array_values(array_unique([$model, $morphClass])))
                        ->whereIn($table.'.commentable_id', $parents->select($parentTable.'.id')));
                }
            });
        }
    }
