    }
    public static function domainDefinitions(): array
    {
        $result = [];
        foreach (self::domainGates() as $domain => [$module]) {
            $records = array_filter(self::records(), static fn (array $record): bool => $record['domain'] === $domain);
            $types = array_keys($records);
            $fields = array_values(array_unique(array_merge(...array_column($records, 'fields'))));
            $entity = ['type' => 'string', 'enum' => $types];
            $selection = ['type' => ['array', 'null'], 'items' => ['type' => 'string', 'enum' => $fields]];
            $id = ['type' => ['integer', 'string'], 'minimum' => 1, 'minLength' => 1, 'maxLength' => 36, 'pattern' => '^(?:[1-9][0-9]*|[0-9a-fA-F-]{36}|[0-9A-HJKMNP-TV-Z]{26})$'];
            $schema = static fn (array $properties): array => ['type' => 'object', 'properties' => $properties, 'required' => array_keys($properties), 'additionalProperties' => false];
            $schemas = ['read' => $schema(['entity_type' => $entity, 'id' => $id, 'fields' => $selection]),
                'search' => $schema(['entity_type' => $entity, 'query' => ['type' => 'string', 'maxLength' => 200], 'project_id' => ['type' => ['integer', 'null'], 'minimum' => 1], 'limit' => ['type' => 'integer', 'minimum' => 1, 'maximum' => 20], 'fields' => $selection]),
                'navigation' => $schema(['entity_type' => $entity, 'id' => $id])];
            $fieldPermissions = array_fill_keys(array_values(array_intersect($fields, self::moneyFields())), ['finance.view']);
            $result[] = new AssistantDomainDefinition($domain, $module, $types[0], [], $fields, $schemas, array_keys($schemas), $records[$types[0]]['navigation'],
                $records[$types[0]]['source'], $types, $fieldPermissions, array_intersect_key(self::entityPermissions(), $records));
        }
        return $result;
    }
}
